    unsafe {
        f.launch(cfg, (dev_ptr, count_dev_ptr))?;
    }

    dev.synchronize()?;
    println!("  Kernel completed.");

    std::thread::sleep(std::time::Duration::from_millis(200));
    hc_buf_ref.signal_shutdown();
