/// Hybrid executor test: WarpFuture PRINT → per-thread compute → WarpFuture PRINT (hybrid-executor.1)
///
/// Validates that a WarpFuture state machine can transition to per-thread divergent
/// computation and back to warp-cooperative I/O. Each lane computes lane_id^2 + 1
/// independently, then all lanes reconverge for the final PRINT.
fn run_hybrid_executor_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Hybrid Executor Test (hybrid-executor.1) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    // Allocate mapped memory for results: 32 u32 values (one per lane) + 1 status
    let (results_host, results_dev) = unsafe { alloc_mapped_result_array(&dev, 33)? };
    let status_dev = results_dev + (32 * std::mem::size_of::<u32>()) as u64;

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let messages = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let msg_clone = std::sync::Arc::clone(&messages);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(move |msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] Hybrid says: \"{text}\"");
            let mut guard = msg_clone.lock().unwrap();
            guard.push(text);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["hybrid_executor_test"]);
    let f = dev
        .get_func("kernel", "hybrid_executor_test")
        .ok_or(GpuHostError::KernelNotFound("hybrid_executor_test"))?;

    // Launch: 1 block x 32 threads (1 full warp)
    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr, results_dev, status_dev as u64))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let status_host = unsafe { results_host.add(32) };
    let status_val = unsafe { std::ptr::read_volatile(status_host) };
    let msgs = messages.lock().unwrap();

    println!("  Status: {status_val} (1=success)");
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);
    println!("  Messages received: {}", msgs.len());

    // Verify per-thread computation results: results[i] = i*i + 1
    let mut compute_ok = true;
    for i in 0u32..32 {
        let actual = unsafe { std::ptr::read_volatile(results_host.add(i as usize)) };
        let expected = i * i + 1;
        if actual != expected {
            println!("  FAIL: results[{i}] = {actual} (expected {expected})");
            compute_ok = false;
        }
    }

    // Verify messages: expect "hybrid: start" and "hybrid: done"
    let msg_ok =
        msgs.len() == 2 && msgs[0].contains("hybrid: start") && msgs[1].contains("hybrid: done");

    if status_val == 1 && compute_ok && msg_ok {
        println!("  Hybrid Executor: PASSED!");
        println!("    WarpFuture PRINT → per-thread compute (32 lanes, each lane_id^2+1) → WarpFuture PRINT");
        println!(
            "    Demonstrates: warp-cooperative I/O ↔ per-thread divergent computation switching"
        );
    } else {
        println!("  Hybrid Executor: FAILED");
        if !compute_ok {
            println!("    Per-thread computation results incorrect");
        }
        if !msg_ok {
            println!("    Messages: {:?}", *msgs);
        }
    }

    unsafe { free_mapped_mem(results_host)? };
    Ok(())
}

/// Hybrid stress test: variable-duration per-thread work + multiple switching points (hybrid-executor.2)
///
/// 9-state machine with 3 I/O phases and 2 compute phases.
/// COMPUTE1: sum 1..=(lane_id*100+1) — ~3100x duration variance across lanes
/// COMPUTE2: XOR-fold with lane-dependent iteration count
/// Verifies syncwarp handles extreme lane divergence timing.
fn run_hybrid_stress_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Hybrid Stress Test (hybrid-executor.2) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    // 64 results (32 per compute phase) + 1 status = 65 u32
    let (results_host, results_dev) = unsafe { alloc_mapped_result_array(&dev, 65)? };
    let status_dev = results_dev + (64 * std::mem::size_of::<u32>()) as u64;

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let messages = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let msg_clone = std::sync::Arc::clone(&messages);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(move |msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] Stress says: \"{text}\"");
            let mut guard = msg_clone.lock().unwrap();
            guard.push(text);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["hybrid_stress_test"]);
    let f = dev
        .get_func("kernel", "hybrid_stress_test")
        .ok_or(GpuHostError::KernelNotFound("hybrid_stress_test"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr, results_dev, status_dev as u64))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let status_host = unsafe { results_host.add(64) };
    let status_val = unsafe { std::ptr::read_volatile(status_host) };
    let msgs = messages.lock().unwrap();

    println!("  Status: {status_val} (1=success)");
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);
    println!("  Messages received: {}", msgs.len());

    // Verify COMPUTE1: results[i] = sum(1..=(i*100+1)) = (i*100+1)*(i*100+2)/2
    let mut compute1_ok = true;
    let mut compute1_failures = 0u32;
    for i in 0u32..32 {
        let actual = unsafe { std::ptr::read_volatile(results_host.add(i as usize)) };
        let n = i * 100 + 1;
        let expected = n.wrapping_mul(n + 1) / 2;
        if actual != expected {
            if compute1_failures < 3 {
                println!("  FAIL compute1[{i}]: {actual} (expected {expected})");
            }
            compute1_failures += 1;
            compute1_ok = false;
        }
    }

    // Verify COMPUTE2: XOR-fold results — compute expected values on host
    let mut compute2_ok = true;
    let mut compute2_failures = 0u32;
    for i in 0u32..32 {
        let actual = unsafe { std::ptr::read_volatile(results_host.add(32 + i as usize)) };
        let iters = (i + 1) * 50;
        let mut val: u32 = 0xDEAD_0000 | i;
        for _ in 0..iters {
            val ^= val << 13;
            val ^= val >> 17;
            val ^= val << 5;
        }
        if actual != val {
            if compute2_failures < 3 {
                println!("  FAIL compute2[{i}]: 0x{actual:08X} (expected 0x{val:08X})");
            }
            compute2_failures += 1;
            compute2_ok = false;
        }
    }

    // Verify messages: expect "stress: phase1", "stress: phase2", "stress: phase3"
    let msg_ok = msgs.len() == 3
        && msgs[0].contains("stress: phase1")
        && msgs[1].contains("stress: phase2")
        && msgs[2].contains("stress: phase3");

    if status_val == 1 && compute1_ok && compute2_ok && msg_ok {
        println!("  Hybrid Stress Test: PASSED!");
        println!("    9-state machine: 3 I/O phases + 2 compute phases");
        println!("    COMPUTE1: sum(1..=n) verified for all 32 lanes (1..3101 iterations)");
        println!("    COMPUTE2: XOR-fold verified for all 32 lanes (50..1600 iterations)");
        println!("    syncwarp correctly handles ~3100x lane duration variance");
    } else {
        println!("  Hybrid Stress Test: FAILED");
        if !compute1_ok {
            println!("    COMPUTE1: {compute1_failures} failures");
        }
        if !compute2_ok {
            println!("    COMPUTE2: {compute2_failures} failures");
        }
        if !msg_ok {
            println!("    Messages: {:?}", *msgs);
        }
    }

    unsafe { free_mapped_mem(results_host)? };
    Ok(())
}

/// ml-workload.1: f32 math validation on GPU.
fn run_f32_math_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- f32 Math Validation (ml-workload.1) ---");

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["f32_math_test"]);
    let f = dev
        .get_func("kernel", "f32_math_test")
        .ok_or(GpuHostError::KernelNotFound("f32_math_test"))?;

    let mut output: CudaSlice<f32> = dev.alloc_zeros::<f32>(8)?;
    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };
    unsafe {
        f.launch(cfg, (&mut output,))?;
    }
    dev.synchronize()?;

    let result: Vec<f32> = dev.dtoh_sync_copy(&output)?;
    let expected: [f32; 8] = [7.0, 12.0, 2.5, 3.0, 70.0, 5.0, 0.0, 1.0];
    let labels = [
        "add", "mul", "div", "sqrt", "dot", "norm", "cos_orth", "cos_same",
    ];

    let mut all_ok = true;
    for i in 0..8 {
        let ok = (result[i] - expected[i]).abs() < 0.001;
        let status = if ok { "OK" } else { "FAIL" };
        println!(
            "  {}: {} (expected {}) [{}]",
            labels[i], result[i], expected[i], status
        );
        if !ok {
            all_ok = false;
        }
    }

    if all_ok {
        println!("  f32 Math: ALL PASSED!");
        println!("    add, mul, div, sqrt.approx.f32, dot product, norm, cosine similarity");
    } else {
        return Err(GpuHostError::Verification {
            test: "f32_math_test",
            detail: "see above".to_string(),
        });
    }

    Ok(())
}

/// ml-workload.2: GPU-autonomous vector similarity search.
fn run_vector_search_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Vector Similarity Search (ml-workload.2) ---");

    const DIM: usize = 128;
    const K: usize = 10;
    const N: usize = 100; // database size

    // Create database: N random-ish vectors + one planted similar vector
    // Vector i: each dimension = sin(i * d * 0.1) for variety
    let mut db_data: Vec<u8> = Vec::new();
    // Header: N (u32) + dim (u32)
    db_data.extend_from_slice(&(N as u32).to_le_bytes());
    db_data.extend_from_slice(&(DIM as u32).to_le_bytes());

    let mut db_vectors: Vec<Vec<f32>> = Vec::new();
    for i in 0..N {
        let mut vec = Vec::with_capacity(DIM);
        for d in 0..DIM {
            let val = ((i as f32 + 1.0) * (d as f32 + 1.0) * 0.1).sin();
            vec.push(val);
        }
        for &v in &vec {
            db_data.extend_from_slice(&v.to_le_bytes());
        }
        db_vectors.push(vec);
    }
    std::fs::write("vecdb.bin", &db_data).unwrap();
    println!(
        "  Created vecdb.bin ({} vectors × {} dims = {} bytes)",
        N,
        DIM,
        db_data.len()
    );

    // Create query: use db_vectors[42] as query (perfect match at index 42)
    let query_vec = &db_vectors[42];
    let mut query_data: Vec<u8> = Vec::new();
    query_data.extend_from_slice(&(DIM as u32).to_le_bytes());
    for &v in query_vec {
        query_data.extend_from_slice(&v.to_le_bytes());
    }
    std::fs::write("query.bin", &query_data).unwrap();
    println!("  Created query.bin (query = db[42], expect top-1 match at id ~42)");

    // Compute expected top-K on CPU
    let mut cpu_scores: Vec<(usize, f32)> = Vec::new();
    let q_norm: f32 = query_vec.iter().map(|x| x * x).sum::<f32>().sqrt();
    for (i, db_vec) in db_vectors.iter().enumerate() {
        let dot: f32 = query_vec
            .iter()
            .zip(db_vec.iter())
            .map(|(a, b)| a * b)
            .sum();
        let v_norm: f32 = db_vec.iter().map(|x| x * x).sum::<f32>().sqrt();
        let score = if q_norm * v_norm > 0.0 {
            dot / (q_norm * v_norm)
        } else {
            0.0
        };
        cpu_scores.push((i, score));
    }
    cpu_scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
    println!(
        "  CPU reference top-3: {:?}",
        &cpu_scores[..3]
            .iter()
            .map(|(id, s)| format!("id={id} score={s:.4}"))
            .collect::<Vec<_>>()
    );

    // Launch GPU kernel
    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;
    let sb_dev_ptr = hc_buf.sideband_dev_ptr;

    let (status_host, status_dev) = unsafe { alloc_mapped_result_array(&dev, 1)? };
    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(|msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] GPU says: \"{text}\"");
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["vector_search_pipeline"]);
    let f = dev
        .get_func("kernel", "vector_search_pipeline")
        .ok_or(GpuHostError::KernelNotFound("vector_search_pipeline"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    println!("  Launching vector_search_pipeline kernel...");
    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr, sb_dev_ptr, status_dev))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let status_val = unsafe { std::ptr::read_volatile(status_host) };
    println!("  Status: {status_val} (1=success)");
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);

    // Read and verify results
    let result_data = std::fs::read("results.bin").map_err(|e| GpuHostError::Verification {
        test: "vector_search_pipeline",
        detail: format!("failed to read results.bin: {e}"),
    })?;

    let result_k = u32::from_le_bytes(result_data[0..4].try_into().unwrap()) as usize;
    println!("  Results: K={result_k}");

    let mut gpu_results: Vec<(u32, f32)> = Vec::new();
    for i in 0..result_k.min(K) {
        let off = 4 + i * 8;
        if off + 8 > result_data.len() {
            break;
        }
        let id = u32::from_le_bytes(result_data[off..off + 4].try_into().unwrap());
        let score = f32::from_le_bytes(result_data[off + 4..off + 8].try_into().unwrap());
        gpu_results.push((id, score));
        println!("    rank {}: id={} score={:.4}", i + 1, id, score);
    }

    // Clean up
    let _ = std::fs::remove_file("vecdb.bin");
    let _ = std::fs::remove_file("query.bin");
    let _ = std::fs::remove_file("results.bin");
    unsafe { free_mapped_mem(status_host)? };

    // Verify: top-1 result should be vector 42 with score ~1.0
    // Full warp merge: all 32 lanes contribute, so we see all 100 vectors.
    // Lane 10 processes vectors 10, 42, 74 — so id=42 should be in the results.

    let top1_ok = !gpu_results.is_empty() && gpu_results[0].0 == 42 && gpu_results[0].1 > 0.99;

    if status_val == 1 && top1_ok {
        println!("  Vector Search Pipeline: PASSED!");
        println!("    GPU self-coordinated: open(db)→read→close→open(query)→read→close→compute→write(results)");
        println!("    {N} database vectors × {DIM} dimensions, top-{result_k} returned");
        println!("    Full warp merge: all 32 lanes contribute via shfl.sync (100% DB coverage)");
        println!(
            "    Top-1: id={} score={:.4} (exact match!)",
            gpu_results[0].0, gpu_results[0].1
        );
    } else {
        println!("  Vector Search Pipeline: FAILED");
        return Err(GpuHostError::Verification {
            test: "vector_search_pipeline",
            detail: format!("status={status_val}, results={gpu_results:?}"),
        });
    }

    Ok(())
}

fn run_batch_search_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Batch Vector Search (ml-workload.3) ---");

    const DIM: usize = 128;
    const N: usize = 100; // database size
    const NUM_QUERIES: usize = 5;

    // Create database (same as ml-workload.2)
    let mut db_data: Vec<u8> = Vec::new();
    db_data.extend_from_slice(&(N as u32).to_le_bytes());
    db_data.extend_from_slice(&(DIM as u32).to_le_bytes());

    let mut db_vectors: Vec<Vec<f32>> = Vec::new();
    for i in 0..N {
        let mut vec = Vec::with_capacity(DIM);
        for d in 0..DIM {
            let val = ((i as f32 + 1.0) * (d as f32 + 1.0) * 0.1).sin();
            vec.push(val);
        }
        for &v in &vec {
            db_data.extend_from_slice(&v.to_le_bytes());
        }
        db_vectors.push(vec);
    }
    std::fs::write("vecdb.bin", &db_data).unwrap();
    println!("  Created vecdb.bin ({N} vectors)");

    // Create queries: use db[10], db[42], db[77], db[3], db[95]
    let query_indices = [10usize, 42, 77, 3, 95];
    let mut queries_data: Vec<u8> = Vec::new();
    queries_data.extend_from_slice(&(NUM_QUERIES as u32).to_le_bytes());
    queries_data.extend_from_slice(&(DIM as u32).to_le_bytes());
    for &qi in &query_indices {
        for &v in &db_vectors[qi] {
            queries_data.extend_from_slice(&v.to_le_bytes());
        }
    }
    std::fs::write("queries.bin", &queries_data).unwrap();
    println!("  Created queries.bin ({NUM_QUERIES} queries: {query_indices:?})");

    // Compute CPU reference scores for each query
    for (qn, &qi) in query_indices.iter().enumerate() {
        let query_vec = &db_vectors[qi];
        let q_norm: f32 = query_vec.iter().map(|x| x * x).sum::<f32>().sqrt();
        let mut scores: Vec<(usize, f32)> = Vec::new();
        for (i, db_vec) in db_vectors.iter().enumerate() {
            let dot: f32 = query_vec
                .iter()
                .zip(db_vec.iter())
                .map(|(a, b)| a * b)
                .sum();
            let v_norm: f32 = db_vec.iter().map(|x| x * x).sum::<f32>().sqrt();
            let score = if q_norm * v_norm > 0.0 {
                dot / (q_norm * v_norm)
            } else {
                0.0
            };
            scores.push((i, score));
        }
        scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        println!(
            "  CPU query {}: top-1 = id={} score={:.4}",
            qn, scores[0].0, scores[0].1
        );
    }

    // Launch GPU kernel
    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;
    let sb_dev_ptr = hc_buf.sideband_dev_ptr;

    let (status_host, status_dev) = unsafe { alloc_mapped_result_array(&dev, 1)? };
    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(|msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] GPU says: \"{text}\"");
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["batch_search_pipeline"]);
    let f = dev
        .get_func("kernel", "batch_search_pipeline")
        .ok_or(GpuHostError::KernelNotFound("batch_search_pipeline"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    println!("  Launching batch_search_pipeline kernel ({NUM_QUERIES} queries)...");
    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr, sb_dev_ptr, status_dev))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let status_val = unsafe { std::ptr::read_volatile(status_host) };
    println!("  Status: {status_val} (1=success)");
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);

    // Read and verify results
    let result_data =
        std::fs::read("batch_results.bin").map_err(|e| GpuHostError::Verification {
            test: "batch_search_pipeline",
            detail: format!("failed to read batch_results.bin: {e}"),
        })?;

    let result_nq = u32::from_le_bytes(result_data[0..4].try_into().unwrap()) as usize;
    let result_k = u32::from_le_bytes(result_data[4..8].try_into().unwrap()) as usize;
    println!("  Results: num_queries={result_nq}, K={result_k}");

    for qi in 0..result_nq.min(NUM_QUERIES) {
        let base = 8 + qi * result_k * 8;
        print!("  Query {qi}: ");
        let mut first_score = 0.0f32;
        for ri in 0..result_k.min(3) {
            let off = base + ri * 8;
            if off + 8 > result_data.len() {
                break;
            }
            let id = u32::from_le_bytes(result_data[off..off + 4].try_into().unwrap());
            let score = f32::from_le_bytes(result_data[off + 4..off + 8].try_into().unwrap());
            if ri == 0 {
                first_score = score;
            }
            print!("[id={id} s={score:.4}] ");
        }
        println!();
        if first_score <= 0.0 {
            println!("  WARNING: query {qi} top-1 score <= 0");
        }
    }

    // Clean up
    let _ = std::fs::remove_file("vecdb.bin");
    let _ = std::fs::remove_file("queries.bin");
    let _ = std::fs::remove_file("batch_results.bin");
    unsafe { free_mapped_mem(status_host)? };

    if status_val == 1 && result_nq == NUM_QUERIES {
        println!("  Batch Search Pipeline: PASSED!");
        println!("    {NUM_QUERIES} queries processed in single kernel launch");
        println!("    DB read once, queries read once, results written once");
        println!(
            "    Amortized: {:.3}ms per query (total {:.3}ms)",
            elapsed.as_secs_f64() * 1000.0 / NUM_QUERIES as f64,
            elapsed.as_secs_f64() * 1000.0
        );
    } else {
        println!("  Batch Search Pipeline: FAILED");
        return Err(GpuHostError::Verification {
            test: "batch_search_pipeline",
            detail: format!("status={status_val}, nq={result_nq}"),
        });
    }

    Ok(())
}

/// async-pipeline demo: GPU-autonomous file transform pipeline.
///
/// The GPU self-coordinates the entire pipeline in one kernel launch:
///   open(in) → read(in) → transform(per-thread) → open(out) → write(out) → close(in) → close(out) → print
///
/// No CPU intervention between steps.
fn run_file_transform_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- File Transform Pipeline (async-pipeline.1+2) ---");

    // Create 1024 bytes of ASCII input: repeating "Hello, GPU Pipeline! " pattern
    let pattern = b"Hello, GPU Pipeline! ";
    let mut input_data = Vec::with_capacity(1024);
    while input_data.len() < 1024 {
        let remaining = 1024 - input_data.len();
        let chunk = remaining.min(pattern.len());
        input_data.extend_from_slice(&pattern[..chunk]);
    }
    std::fs::write("gpu_input.txt", &input_data).map_err(|e| GpuHostError::Verification {
        test: "file_transform_pipeline",
        detail: format!("failed to create input file: {e}"),
    })?;
    println!("  Created gpu_input.txt ({} bytes)", input_data.len());

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;
    let sb_dev_ptr = hc_buf.sideband_dev_ptr;

    let (status_host, status_dev) = unsafe { alloc_mapped_result_array(&dev, 1)? };

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let messages = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let msg_clone = std::sync::Arc::clone(&messages);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(move |msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] GPU says: \"{text}\"");
            let mut guard = msg_clone.lock().unwrap();
            guard.push(text);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["file_transform_pipeline"]);
    let f = dev
        .get_func("kernel", "file_transform_pipeline")
        .ok_or(GpuHostError::KernelNotFound("file_transform_pipeline"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    println!("  Launching file_transform_pipeline kernel...");
    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr, sb_dev_ptr, status_dev))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let status_val = unsafe { std::ptr::read_volatile(status_host) };
    let msgs = messages.lock().unwrap();

    println!("  Status: {status_val} (1=success)");
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);

    // Verify output file exists and contains case-toggled content
    let output_data = std::fs::read("gpu_output.txt").map_err(|e| GpuHostError::Verification {
        test: "file_transform_pipeline",
        detail: format!("failed to read output file: {e}"),
    })?;

    // Expected: toggle ASCII case on the input
    let expected: Vec<u8> = input_data
        .iter()
        .map(|&b| {
            if b.is_ascii_uppercase() || b.is_ascii_lowercase() {
                b ^ 0x20
            } else {
                b
            }
        })
        .collect();

    let content_ok = output_data == expected;
    let msg_ok = msgs.iter().any(|m| m.contains("pipeline: done"));

    // Clean up
    let _ = std::fs::remove_file("gpu_input.txt");
    let _ = std::fs::remove_file("gpu_output.txt");
    unsafe { free_mapped_mem(status_host)? };

    if status_val == 1 && content_ok && msg_ok {
        println!("  File Transform Pipeline: PASSED!");
        println!("    16-state WarpFuture: open→read→transform→open→write→close→close→print");
        println!("    GPU self-coordinated {} I/O steps + 1 compute step", 8);
        println!(
            "    {} bytes: ASCII case toggled correctly",
            output_data.len()
        );
        println!("    Zero CPU intervention between steps");
    } else {
        println!("  File Transform Pipeline: FAILED");
        if status_val != 1 {
            println!("    Status: {status_val}");
        }
        if !content_ok {
            println!(
                "    Content mismatch: output {} bytes, expected {} bytes",
                output_data.len(),
                expected.len()
            );
            if !output_data.is_empty() {
                let first = std::cmp::min(32, output_data.len());
                println!("    Output[..{}]: {:?}", first, &output_data[..first]);
                println!("    Expected[..{}]: {:?}", first, &expected[..first]);
            }
        }
        if !msg_ok {
            println!("    Missing 'pipeline: done' message. Got: {:?}", *msgs);
        }
        return Err(GpuHostError::Verification {
            test: "file_transform_pipeline",
            detail: "see above".to_string(),
        });
    }

    Ok(())
}

/// GPU panic handler test: verify panic message is received via hostcall.
///
/// The test kernel deliberately panics. We expect:
/// 1. The panic message appears on stderr via [GPU PANIC] prefix
/// 2. The kernel returns a CUDA error (due to trap instruction)
/// 3. The result marker is set to 1 (written before the panic)
fn run_panic_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- GPU Panic Handler Test (gpu-panic.2) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    let (result_host_ptr, result_dev_ptr) = unsafe { alloc_mapped_result_array(&dev, 1)? };

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);
    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(|msg| {
            let s = std::str::from_utf8(msg).unwrap_or("<invalid>");
            println!("  [GPU PRINT] {s}");
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "panic_test", &["panic_test_kernel"]);
    let f = dev
        .get_func("panic_test", "panic_test_kernel")
        .ok_or(GpuHostError::KernelNotFound("panic_test_kernel"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (1, 1, 1),
        shared_mem_bytes: 0,
    };

    println!("  Launching panic_test_kernel (expects GPU panic + trap)...");
    unsafe {
        f.launch(cfg, (dev_ptr, result_dev_ptr))?;
    }

    // Use raw CUDA API for synchronization since cudarc's synchronize may
    // unwrap internally. trap instruction will cause CUDA_ERROR_LAUNCH_FAILED.
    let sync_result = unsafe {
        let cu = cuda_lib();
        cu.cuCtxSynchronize()
    };

    // Give listener time to process the panic packet
    std::thread::sleep(std::time::Duration::from_millis(200));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let marker = unsafe { std::ptr::read_volatile(result_host_ptr) };

    println!("  Result marker: {marker} (expected 1 = reached panic point)");
    println!("  CUDA sync result: {sync_result:?} (LAUNCH_FAILED expected from trap)");

    // The test passes if:
    // 1. The marker was set to 1 (code reached the panic point)
    // 2. The [GPU PANIC] message appeared on stderr (visible in console output)
    if marker == 1 {
        println!("  panic_test: PASSED (panic message sent via hostcall before trap)");
    } else {
        println!("  panic_test: marker was {marker} (expected 1)");
    }

    // IMPORTANT: trap instruction puts the CUDA context in an error state.
    // CudaDevice's Drop impl will try to sync and panic on the sticky error.
    // Exit the process cleanly before Drop runs.
    println!("  Note: Exiting to avoid CudaDevice Drop panic after trap.");
    std::process::exit(0);
}

